<?php if (!$note): ?><main class="hq-section"><div class="section-label"><span>404</span><span>Field Note</span></div><h1 class="dossier-title">Note not found.</h1><a class="hq-button hq-button--primary" href="/blog">Back to notes ↗</a></main><?php else: ?><main class="hq-section note-page"><div class="section-label"><span><?= e($note['type']) ?></span><span><?= e($note['date']) ?></span></div><p class="eyebrow"><span class="signal-dot"></span> FIELD NOTE / <?= e($note['date']) ?></p><h1 class="dossier-title"><?= e($note['title']) ?></h1><p class="dossier-lede"><?= e($note['excerpt']) ?></p><article class="note-prose"><?php foreach($note['body'] as $paragraph): ?><p><?= e($paragraph) ?></p><?php endforeach; ?></article><div class="dossier-actions"><a class="hq-text-link" href="/blog">← Field Notes archive</a><a class="hq-button hq-button--outline" href="/contact">Respond with a thought ↗</a></div></main><?php endif; ?>
